const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symptoms=['Nausea','Vomiting','Diarrhoea','Constipation','Abdominal discomfort','Reduced appetite','Fatigue','Dizziness'];
const severity=['None','Mild','Moderate','Severe','Not sure'];
let role='patient',page='overview',step=0,filter='All',selected=null;
let draft={medication:'Ozempic (semaglutide)',status:'',dose:'',lastDose:'',missed:'',changes:'',symptoms:Object.fromEntries(symptoms.map(x=>[x,''])),urgent:[],impact:'',hydration:'',details:'',contact:'',notes:'',confirmed:false};
let reports=[
{id:'R-104',participant:'P-024',period:'Week 04',date:'28 Oct 2026',quality:'Complete',clinical:'Review requested',payment:'Pending',model:'Rule preview · not trained AI',answers:{status:'Taking as prescribed',dose:'Participant recorded 0.5 mg',missed:'No',changes:'No changes reported',symptoms:{Nausea:'Moderate',Vomiting:'None',Diarrhoea:'None',Constipation:'Mild','Abdominal discomfort':'None','Reduced appetite':'Mild',Fatigue:'Mild',Dizziness:'None'},urgent:[],impact:'A little',hydration:'Yes',details:'Nausea is more noticeable the day after my injection.',contact:'Yes',notes:'Could we discuss how this affects my workday?'},audit:['28 Oct · Synthetic report submitted'],decision:''},
{id:'R-103',participant:'P-031',period:'Week 02',date:'27 Oct 2026',quality:'Clarification needed',clinical:'Not reviewed',payment:'Pending',model:'Rule preview · not trained AI',answers:{status:'Paused',dose:'Not sure',missed:'Not sure',changes:'Stopped earlier this week; date not provided.',symptoms:{Nausea:'Not sure'},urgent:[],impact:'Not sure',hydration:'Not sure',details:'Please clarify the reporting dates.',contact:'Yes',notes:''},audit:['27 Oct · Synthetic report submitted'],decision:''},
{id:'R-102',participant:'P-024',period:'Week 03',date:'21 Oct 2026',quality:'Complete',clinical:'Reviewed',payment:'Simulated paid',model:'Rule preview · not trained AI',answers:{status:'Taking as prescribed',dose:'Participant recorded 0.5 mg',missed:'No',changes:'No changes reported',symptoms:{Nausea:'Mild'},urgent:[],impact:'Not at all',hydration:'Yes',details:'',contact:'No',notes:''},audit:['21 Oct · Synthetic report submitted','22 Oct · Clinic approved reward (demo)','22 Oct · Payment simulated; no blockchain transaction'],decision:'Questionnaire complete.'}
];
function badge(t){return '<span class="pill '+(/Pending|Review|Clarification|flag/i.test(t)?'warn':/Not|Draft|preview|training/i.test(t)?'neutral':'')+'">'+esc(t)+'</span>'}
function btn(t,a,cls=''){return '<button class="btn '+cls+'" onclick="'+a+'">'+t+'</button>'}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function nav(p){page=p;selected=null;render();window.scrollTo(0,0)}
function switchRole(r){role=r;page=r==='patient'?'overview':'queue';render()}
function render(){
const menus=role==='patient'?[['overview','◫','Overview'],['checkin','✎','Weekly check-in'],['reports','▤','My reports'],['rewards','◇','My rewards']]:[['queue','▤','Review queue'],['program','◎','Program & model'],['rewards','◇','Reward ledger']];
$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="logo"><span class="mark">↗</span>careloop<span style="color:#829568">.</span></div><div class="sublogo">BETTER FOLLOW-UP</div><nav class="nav" aria-label="Main navigation">'+menus.map(([p,i,t])=>'<button class="'+(page===p?'active':'')+'" onclick="nav(\''+p+'\')"><span>'+i+'</span>'+t+'</button>').join('')+'</nav><div class="sidebottom"><div class="info">Small check-ins.<br>A clearer picture over time.</div><div class="profile"><div class="avatar">'+(role==='patient'?'AL':'CL')+'</div><div>'+ (role==='patient'?'Alex · P-024':'Clinic workspace')+'<small>Fictional demo account</small></div></div></div></aside><div><header class="topbar"><div><strong>GLP-1 follow-up</strong><br><small>Program GLP-01 · Demonstration</small></div><div class="role" aria-label="Demo role switch"><button class="'+(role==='patient'?'active':'')+'" onclick="switchRole(\'patient\')">Participant</button><button class="'+(role==='clinic'?'active':'')+'" onclick="switchRole(\'clinic\')">Clinic</button></div></header><main class="content"><div class="notice">INTERACTIVE PROTOTYPE · Use fictional information only. Changes last until reload. Role switching is a demo, not secure authentication.</div>'+content()+'<div class="footer">Careloop · Thoughtful follow-up, human decisions.</div></main></div></div>';
}
function heading(ey,h,p,tag=''){return '<div class="heading"><div><div class="eyebrow">'+ey+'</div><h1>'+h+'</h1><p>'+p+'</p></div>'+ (tag?badge(tag):'')+'</div>'}
function content(){
if(page==='checkin')return checkin();
if(page==='done')return '<div class="success"><div class="circle">✓</div><h1>Your voice matters.</h1><p>Your demo report is in the clinic queue. You can review the answers and follow its status below.</p><div class="card"><h3>What happens next?</h3><p>Clinic staff review your report and decide on follow-up and reward approval. A symptom concern does not automatically affect your reward.</p>'+badge('Awaiting clinic review')+'</div><br>'+btn('View my reports','nav(\'reports\')')+'</div>';
if(page==='reports')return heading('YOUR CONTRIBUTION','Your reports','A record of your check-ins and the clinic’s responses.')+reportTable(reports.filter(r=>r.participant==='P-024'),false);
if(page==='rewards')return rewards();
if(page==='queue')return selected?detail():queue();
if(page==='program')return program();
return overview();
}
function overview(){const mine=reports.filter(r=>r.participant==='P-024');return heading('PARTICIPANT WORKSPACE','A little check-in. A bigger picture.','Welcome back, Alex. Let’s capture how your week has been.','Week 05 / 52')+
'<section class="hero"><div><div class="eyebrow">YOUR NEXT STEP · ABOUT 4 MINUTES</div><h2>How has this week felt?</h2><p>Share what you noticed—even if nothing changed. Every honest check-in helps your study team understand your experience.</p>'+btn(reports.some(r=>r.participant==='P-024'&&r.period==='Week 05')?'View submitted check-in':'Start weekly check-in',reports.some(r=>r.participant==='P-024'&&r.period==='Week 05')?'nav(\'reports\')':'nav(\'checkin\')')+'</div><div class="plant" aria-hidden="true"><div class="stem"></div><div class="leaf"></div><div class="leaf two"></div></div></section>'+
'<div class="stats"><div class="card stat"><div class="eyebrow">CHECK-INS SHARED</div><div class="num">'+mine.length+'</div><small>Your experience, recorded</small></div><div class="card stat"><div class="eyebrow">DEMO REWARDS</div><div class="num">'+mine.filter(r=>r.payment==='Simulated paid').length*2+' <span style="font-size:14px">tokens</span></div><small>Simulated · no real funds</small></div><div class="card stat"><div class="eyebrow">NEXT CHECK-IN</div><div class="num">Week 05</div><small>23–29 October 2026</small></div></div>'+
'<div class="grid"><section class="card"><div class="row"><h2>Recent check-ins</h2>'+btn('View all ↗','nav(\'reports\')','ghost')+'</div>'+mine.slice(0,3).map(r=>'<div class="row listrow"><div class="flex"><span class="icon">✓</span><div><strong>'+r.period+' check-in</strong><small>'+r.date+'</small></div></div>'+badge(r.payment==='Simulated paid'?'Reward recorded':r.payment)+'</div>').join('')+'</section><section class="card"><div class="eyebrow">YOUR PARTICIPATION</div><h2 style="margin-top:10px">One week at a time</h2><div class="week">'+['01','02','03','04','05','06'].map((x,i)=>'<div>W'+x+'<span class="'+(i===4?'current':'')+'">'+(i<4?'✓':i===4?'•':'–')+'</span></div>').join('')+'</div><p class="muted" style="font-size:13px">Illustrative study timeline. No streak penalties. Pausing treatment or reporting symptoms does not make your experience less valuable.</p></section></div>'+
'<div class="info">This is a draft research questionnaire, not a diagnostic tool. A clinic must approve it before use with real participants.</div>'}
function field(label,html,hint=''){return '<div class="field"><label>'+label+'</label>'+html+(hint?'<small>'+hint+'</small>':'')+'</div>'}
function select(name,options,value){return '<select aria-label="'+esc(name)+'" onchange="draft[\''+name+'\']=this.value"><option value="">Choose an answer</option>'+options.map(v=>'<option '+(v===value?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select>'}
function radios(name,options){return '<div class="choices">'+options.map(v=>'<label class="choice"><input type="radio" name="'+name+'" value="'+esc(v)+'" '+(draft[name]===v?'checked':'')+' onchange="draft[\''+name+'\']=this.value">'+esc(v)+'</label>').join('')+'</div>'}
function text(name,placeholder=''){return '<textarea aria-label="'+name+'" placeholder="'+esc(placeholder)+'" oninput="draft[\''+name+'\']=this.value">'+esc(draft[name])+'</textarea>'}
function checkin(){if(reports.some(r=>r.participant==='P-024'&&r.period==='Week 05'))return heading('WEEK 05','Already submitted','Your report is saved in this demo session.')+btn('View reports','nav(\'reports\')');
let inner='';
if(step===0)inner='<h2>Your treatment this week</h2><p class="muted">Reporting period: 23–29 October 2026. Tell us what happened; this form does not recommend dose changes.</p>'+
field('Medication', '<input type="text" aria-label="Medication" value="'+esc(draft.medication)+'" oninput="draft.medication=this.value">')+
field('Current treatment status',select('status',['Taking as prescribed','Taking, but differently from the prescription','Paused','Stopped','Not started','Not sure'],draft.status))+
field('Most recent dose you actually took (optional)','<input type="text" aria-label="Most recent dose" value="'+esc(draft.dose)+'" placeholder="For example: 0.5 mg, or not sure" oninput="draft.dose=this.value">','Record only; no dose recommendation is generated.')+
field('Date of most recent dose (optional)','<input type="date" aria-label="Last dose date" max="2026-10-29" value="'+draft.lastDose+'" onchange="draft.lastDose=this.value">')+
field('Were any scheduled doses missed or delayed?',radios('missed',['No','Yes','Not applicable','Not sure']))+
field('Any change in medication, dose, or treatment status? (optional)',text('changes','Describe what changed and when, if known.'));
if(step===1)inner='<h2>What have you noticed?</h2><p class="muted">Rate your experience over the past 7 days. These questions do not assume the medication caused a symptom.</p><small>Mild: noticeable · Moderate: affects some activities · Severe: substantially disrupts activities. These are draft response labels.</small>'+
symptoms.map(s=>'<div class="symrow"><label for="sym-'+symptoms.indexOf(s)+'">'+s+'</label><select id="sym-'+symptoms.indexOf(s)+'" onchange="draft.symptoms[\''+s+'\']=this.value"><option value="">Choose</option>'+severity.map(v=>'<option '+(draft.symptoms[s]===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div>').join('')+
field('When did symptoms start or change? (optional)',text('details','Mention timing, duration, or anything else the clinic should know.'));
if(step===2)inner='<h2>Your daily life & follow-up</h2>'+
field('How much did symptoms affect your usual activities?',radios('impact',['Not at all','A little','Quite a bit','Unable to do usual activities','Not sure']))+
field('Have you been able to drink and keep fluids down?',radios('hydration',['Yes','With difficulty','No','Not sure']))+
field('Would you like the clinic to contact you?',radios('contact',['No','Yes']))+
'<fieldset class="field"><legend>Did you experience any of these? Select all that apply.</legend><div style="display:grid;gap:9px">'+['Severe, persistent abdominal pain','Sudden loss or rapid worsening of vision','Difficulty breathing or swelling of face / throat'].map(v=>'<label class="choice"><input type="checkbox" '+(draft.urgent.includes(v)?'checked':'')+' onchange="toggleUrgent(\''+v+'\',this.checked)">'+v+'</label>').join('')+'</div></fieldset><div class="urgent"><strong>Do not wait for an app response.</strong> For difficulty breathing or face/throat swelling, seek emergency help. For severe persistent abdominal pain or sudden vision changes, seek urgent medical care. This prototype is not monitored and sends no alerts.</div>'+
field('Anything else for the clinic? (optional)',text('notes','Other symptoms, treatment changes, or a question for your clinic.'));
if(step===3)inner='<h2>Review your check-in</h2><p class="muted">You can go back to change any answer. Reporting symptoms does not reduce your fixed completion reward.</p>'+answerSummary(draft)+
'<div class="summary"><strong>What your clinic will see</strong><p>Your original answers and a demonstration of report-quality flags. No trained AI is running, and no doctor will be notified by this prototype.</p></div>'+
'<label class="check"><input type="checkbox" '+(draft.confirmed?'checked':'')+' onchange="draft.confirmed=this.checked">I am submitting fictional demo information and understand this is not a live clinical service.</label>';
return '<div class="formwrap">'+heading('WEEK 05 CHECK-IN','Your week, in your words.','A few minutes for a clearer picture.')+'<div class="steps">'+['Treatment','Symptoms','Daily life','Review'].map((t,i)=>'<div class="'+(i<=step?'on':'')+'">'+(i+1)+'. '+t+'</div>').join('')+'</div><div class="card">'+inner+'<div id="formError" class="error" role="alert"></div><div class="actions">'+btn(step?'← Back':'Save for this session',step?'moveStep(-1)':'nav(\'overview\')','secondary')+btn(step===3?'Submit demo report →':'Continue →',step===3?'submitReport()':'moveStep(1)')+'</div></div><p class="muted" style="font-size:11px">Draft questionnaire v0.1 · Requires clinic validation. Symptom topics informed by <a href="https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic" target="_blank" rel="noopener">EMA product information</a>; not a validated clinical scale.</p></div>'}
function toggleUrgent(v,c){draft.urgent=c?[...draft.urgent,v]:draft.urgent.filter(x=>x!==v)}
function moveStep(d){if(d>0){let e=step===0&&(!draft.status||!draft.missed)?'Please answer the treatment status and missed-dose questions.':step===1&&symptoms.some(s=>!draft.symptoms[s])?'Please select a response for each symptom. “Not sure” is available.':step===2&&(!draft.impact||!draft.hydration||!draft.contact)?'Please answer the daily-life and contact questions.':'';if(e){$('#formError').textContent=e;return}}step+=d;render();window.scrollTo(0,0)}
function submitReport(){if(!draft.confirmed){$('#formError').textContent='Please confirm that you are using fictional information.';return}if(reports.some(r=>r.participant==='P-024'&&r.period==='Week 05'))return;
const a=JSON.parse(JSON.stringify(draft));reports.unshift({id:'R-105',participant:'P-024',period:'Week 05',date:'29 Oct 2026',quality:Object.values(a.symptoms).includes('Not sure')?'Clarification needed':'Complete',clinical:a.urgent.length?'Priority review':a.contact==='Yes'||Object.values(a.symptoms).includes('Severe')?'Review requested':'Not reviewed',payment:'Pending',model:'Rule preview · not trained AI',answers:a,audit:['29 Oct · Participant submitted a demo report'],decision:''});page='done';render();window.scrollTo(0,0)}
function answerSummary(a){return [['Treatment status',a.status],['Recorded dose',a.dose||'Not provided'],['Most recent dose',a.lastDose||'Not provided'],['Missed / delayed doses',a.missed],['Treatment changes',a.changes||'None described'],['Symptoms',Object.entries(a.symptoms||{}).map(([k,v])=>k+': '+v).join('; ')],['Symptom timing',a.details||'Not provided'],['Daily activities',a.impact],['Keeping fluids down',a.hydration],['Contact requested',a.contact],['Concern indicators',(a.urgent||[]).join('; ')||'None selected'],['Additional notes',a.notes||'None']].map(([k,v])=>'<div class="keyval"><span>'+k+'</span><div>'+esc(v)+'</div></div>').join('')}
function reportTable(rs,clinic){return '<div class="card tablewrap"><table><thead><tr><th>REPORT</th><th>'+(clinic?'PARTICIPANT':'DATE')+'</th><th>CLINICAL REVIEW</th><th>REWARD</th><th></th></tr></thead><tbody>'+rs.map(r=>'<tr><td><strong>'+r.period+'</strong><br><small>'+r.id+'</small></td><td>'+esc(clinic?r.participant:r.date)+'</td><td>'+badge(r.clinical)+'</td><td>'+badge(r.payment)+'</td><td>'+btn(clinic?'Review →':'Open →','openReport(\''+r.id+'\')','secondary')+'</td></tr>').join('')+'</tbody></table>'+(rs.length?'':'<div class="empty">No reports in this view.</div>')+'</div>'}
function openReport(id){selected=id;if(role==='patient'){page='reportDetail';$('#app');renderPatientDetail()}else{page='queue';render()}window.scrollTo(0,0)}
const originalContent=content;content=function(){if(page==='reportDetail'){const r=reports.find(r=>r.id===selected);return heading('YOUR REPORT',r.period+' check-in',r.date)+btn('← All reports','nav(\'reports\')','ghost')+'<div class="grid"><div class="card">'+answerSummary(r.answers)+'</div><div class="card"><h2>Clinic response</h2>'+badge(r.clinical)+'<p>'+esc(r.decision||'Awaiting clinic review.')+'</p><h3>Reward status</h3>'+badge(r.payment)+'<p class="muted">2 demo tokens per approved check-in. No real payment is made.</p></div></div>'}return originalContent()};
function renderPatientDetail(){render()}
function queue(){const rs=reports.filter(r=>filter==='All'||filter==='Needs review'&&r.clinical!=='Reviewed'||filter==='Pending rewards'&&r.payment==='Pending');return heading('CLINIC WORKSPACE','The people behind the reports.','Review original answers, follow up, and approve rewards separately.','GLP-01')+
'<div class="stats"><div class="card stat"><div class="eyebrow">REPORTS</div><div class="num">'+reports.length+'</div><small>This demo workspace</small></div><div class="card stat"><div class="eyebrow">AWAITING REVIEW</div><div class="num">'+reports.filter(r=>r.clinical!=='Reviewed').length+'</div><small>Clinic decisions required</small></div><div class="card stat"><div class="eyebrow">MODEL STATUS</div><div class="num" style="font-size:22px">Not trained</div><small>Rule preview only</small></div></div>'+
'<div class="tabs">'+['All','Needs review','Pending rewards'].map(t=>'<button class="'+(t===filter?'active':'')+'" onclick="filter=\''+t+'\';render()">'+t+'</button>').join('')+'</div>'+reportTable(rs,true)}
function detail(){const r=reports.find(x=>x.id===selected);return heading('CLINIC REVIEW',r.participant+' · '+r.period,'Original answers stay visible. Clinical action and payment are separate.')+btn('← Review queue','nav(\'queue\')','ghost')+
'<div class="detail"><section class="card"><div class="row"><h2>Participant report</h2>'+badge(r.quality)+'</div>'+answerSummary(r.answers)+'</section><div><section class="card"><div class="row"><h2>Assessment preview</h2>'+badge('No trained AI')+'</div><div class="summary"><strong>Deterministic demonstration</strong><ul><li>'+esc(r.quality==='Complete'?'Required responses present.':'Some information needs clarification.')+'</li><li>'+esc(r.answers.contact==='Yes'?'Participant requested contact.':'No contact request recorded.')+'</li><li>'+esc(r.answers.urgent?.length?'Participant selected a priority concern.':'No priority checkbox selected. This does not establish medical safety.')+'</li></ul></div><small>Program model: GLP-01 · training pending. This is not a clinical assessment.</small></section>'+
'<section class="card" style="margin-top:18px"><h2>Clinic decision</h2>'+badge(r.clinical)+field('Review note', '<textarea id="decision" placeholder="Record a follow-up or clarification for this demo.">'+esc(r.decision)+'</textarea>')+'<div style="display:flex;gap:8px;flex-wrap:wrap">'+btn('Mark reviewed','clinicAction(\'review\')')+btn('Request clarification','clinicAction(\'clarify\')','secondary')+'</div><p class="muted" style="font-size:12px">Actions update this demo only. No message or medical alert is sent.</p></section>'+
'<section class="card" style="margin-top:18px"><h2>Completion reward</h2><div class="row"><strong>2 demo tokens</strong>'+badge(r.payment)+'</div><p class="muted" style="font-size:13px">Approval confirms eligibility and reporting completion—not absence of symptoms.</p><label class="check"><input id="eligible" type="checkbox" '+(r.payment!=='Pending'?'disabled':'')+'>I confirm eligibility and that this reporting period has not already been rewarded.</label><br><button class="btn" '+(r.payment!=='Pending'?'disabled':'')+' onclick="clinicAction(\'approve\')">Approve reward (demo)</button><p id="clinicError" class="error" role="alert"></p><small>Clinic signing key and Cardano contract are not connected.</small></section>'+
'<section class="card" style="margin-top:18px"><h2>Activity</h2>'+r.audit.map(t=>'<div class="audit">'+esc(t)+'</div>').join('')+'</section></div></div>'}
function clinicAction(a){if(role!=='clinic')return;const r=reports.find(x=>x.id===selected),note=$('#decision').value.trim();if(a==='approve'){if(!$('#eligible').checked){$('#clinicError').textContent='Confirm eligibility and duplicate checking first.';return}if(r.payment!=='Pending')return;r.payment='Approved';r.audit.push('29 Oct · Clinic reward approval simulated (no signature created)');notify('Demo reward approved. No funds moved.')}else{if(!note){$('#decision').focus();notify('Add a review note first.');return}r.decision=note;r.clinical=a==='review'?'Reviewed':'Clarification requested';r.audit.push('29 Oct · Clinic '+(a==='review'?'marked reviewed':'requested clarification')+' (demo)');notify('Clinic review saved in this session.')}render()}
function rewards(){const rs=role==='patient'?reports.filter(r=>r.participant==='P-024'):reports;return heading('TRANSPARENT REWARDS',role==='patient'?'Your contribution, recognised.':'Reward ledger','Fixed rewards for participation. Clinical findings never change the amount.','Simulation only')+
'<div class="grid"><div class="card"><div class="eyebrow">SIMULATED PAYMENTS</div><div class="balance">'+rs.filter(r=>r.payment==='Simulated paid').length*2+' <span style="font-size:22px">tokens</span></div><p class="muted">No wallet connected. No on-chain transaction or real balance exists.</p></div><div class="card"><h2>How it works</h2><p>1. Submit a check-in.<br>2. Clinic approves completion and eligibility.<br>3. The future contract checks approval and duplicate claims.<br>4. Tokens reach the participant’s wallet.</p></div></div><div class="card tablewrap" style="margin-top:22px"><table><thead><tr><th>CLAIM</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>'+rs.map(r=>'<tr><td>'+r.participant+' · '+r.period+'</td><td>2 demo tokens</td><td>'+badge(r.payment)+'</td><td>'+(role==='clinic'&&r.payment==='Approved'?btn('Simulate settlement','settle(\''+r.id+'\')','secondary'):'—')+'</td></tr>').join('')+'</tbody></table></div>'}
function settle(id){if(role!=='clinic')return;const r=reports.find(x=>x.id===id);if(r.payment!=='Approved')return;if(reports.some(x=>x.id!==id&&x.participant===r.participant&&x.period===r.period&&x.payment==='Simulated paid')){notify('Duplicate claim rejected.');return}r.payment='Simulated paid';r.audit.push('29 Oct · Settlement simulated; no blockchain transaction');render();notify('Simulation recorded. No actual payment.')}
function program(){return heading('PROGRAM CONFIGURATION','One program. Its own trained AI.','The assignment follows the enrollment—not the participant’s choice.','Draft configuration')+
'<div class="grid"><section class="card"><h2>GLP-1 treatment follow-up</h2>'+[['Program ID','GLP-01'],['Medication focus','Ozempic / semaglutide'],['Questionnaire','Weekly check-in · v0.1 draft'],['Reporting schedule','7-day recall · illustrative 52 weeks'],['Responsible clinic','Demo Clinic A'],['Reward','2 demo tokens per approved period'],['Contract','Not deployed · Cardano preprod planned']].map(([k,v])=>'<div class="keyval"><span>'+k+'</span><strong>'+v+'</strong></div>').join('')+'</section><section class="card"><h2>Program-specific AI</h2>'+badge('Training pending')+'<p>We will train and evaluate a dedicated model for this program. The current interface uses explicit demo rules.</p><div class="progress"><div></div></div><div class="keyval"><span>Training data</span><div>Not connected</div></div><div class="keyval"><span>Model version</span><div>None deployed</div></div><div class="keyval"><span>Clinic validation</span><div>Pending</div></div><p class="info">Each new program requires its own trained model and clinic-approved criteria before activation.</p></section></div><section class="card" style="margin-top:22px"><h2>Questionnaire scope</h2><p>Treatment exposure, missed or delayed doses, symptoms and timing, daily impact, fluid tolerance, and requested follow-up. Continuing, pausing, and stopping treatment are all supported.</p><p class="muted">Draft for interface testing, not a validated clinical instrument. Reference: <a target="_blank" rel="noopener" href="https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic">EMA Ozempic product information</a>.</p></section>'}
render();

